"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[166],{1981:e=>{e.exports=JSON.parse('{"functions":[{"name":"registerSchema","desc":"Registers a new schema for data storage.\\n\\n\\n```lua\\nlocal PlayerSchema = Coppermind.registerSchema({\\n\\tname = \\"PlayerData\\",\\n\\tdataTemplate = {\\n\\t\\tcoins = 0,\\n\\t\\tgems = 0,\\n\\t\\tinventory = {},\\n\\t},\\n\\tmigrations = {},\\n})\\n```","params":[{"name":"schema","desc":"The schema definition","lua_type":"Schema<T>"}],"returns":[{"desc":"The registered schema","lua_type":"Schema<T>"}],"function_type":"static","source":{"line":224,"path":"src/init.luau"}},{"name":"getSchema","desc":"Retrieves a registered schema by name.","params":[{"name":"name","desc":"The schema name","lua_type":"string"}],"returns":[{"desc":"The schema, or nil if not found","lua_type":"Schema?"}],"function_type":"static","source":{"line":242,"path":"src/init.luau"}},{"name":"getStore","desc":"Gets a reference to a loaded store.","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"The store, or nil if not loaded","lua_type":"Store<T>?"}],"function_type":"static","source":{"line":254,"path":"src/init.luau"}},{"name":"saveStore","desc":"Saves a store\'s data to the DataStore.","params":[{"name":"schema","desc":"The schema","lua_type":"Schema"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"Whether the save was queued successfully","lua_type":"boolean"}],"function_type":"static","source":{"line":269,"path":"src/init.luau"}},{"name":"loadStore","desc":"Loads a store from the DataStore.\\n\\n\\n```lua\\nlocal store = Coppermind.loadStore(PlayerSchema, tostring(player.UserId), {\\n\\tsessionLocked = true,\\n\\tautoSave = 60,\\n})\\n\\nstore.onReady:Connect(function()\\n\\tprint(\\"Data loaded!\\")\\nend)\\n```","params":[{"name":"schema","desc":"The schema to use","lua_type":"Schema<T>"},{"name":"key","desc":"Unique identifier for this data entry","lua_type":"string"},{"name":"config","desc":"Optional configuration","lua_type":"StoreConfig?"}],"returns":[{"desc":"The store object (data loads asynchronously)","lua_type":"Store<T>"}],"function_type":"static","source":{"line":345,"path":"src/init.luau"}},{"name":"unloadStore","desc":"Unloads a store, saving its data and releasing any session lock.\\n\\n\\n```lua\\ngame.Players.PlayerRemoving:Connect(function(player)\\n\\tCoppermind.unloadStore(PlayerSchema, tostring(player.UserId))\\nend)\\n```","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"Whether the unload was queued successfully","lua_type":"boolean"}],"function_type":"static","source":{"line":425,"path":"src/init.luau"}},{"name":"isLoaded","desc":"Checks if a store is currently loaded.","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"Whether the store is loaded","lua_type":"boolean"}],"function_type":"static","source":{"line":475,"path":"src/init.luau"}},{"name":"getData","desc":"Gets the current data for a store.\\n\\n:::caution Data is Immutable\\nThe returned data is frozen and cannot be modified directly.\\nUse `updateData` to make changes.\\n:::","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"The data, or nil if not available","lua_type":"T?"}],"function_type":"static","source":{"line":493,"path":"src/init.luau"}},{"name":"updateData","desc":"Updates a store\'s data safely.\\n\\nThe callback receives a mutable copy of the data. Either mutate it directly\\nand return nil, or return a new table to replace the data entirely.\\n\\n\\n```lua\\n-- Mutation style\\nCoppermind.updateData(PlayerSchema, key, function(data)\\n\\tdata.coins += 100\\n\\treturn nil\\nend)\\n\\n-- Replacement style\\nCoppermind.updateData(PlayerSchema, key, function(data)\\n\\treturn { coins = data.coins + 100, gems = data.gems }\\nend)\\n```","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"},{"name":"callback","desc":"The update function","lua_type":"(data: T) -> T?"}],"returns":[{"desc":"Whether the update was successful","lua_type":"boolean"}],"function_type":"static","source":{"line":542,"path":"src/init.luau"}},{"name":"setMockMode","desc":"Enables or disables mock mode for testing.\\n\\nIn mock mode, data is stored in memory instead of DataStores.","params":[{"name":"enabled","desc":"Whether to enable mock mode","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":590,"path":"src/init.luau"}},{"name":"isMockMode","desc":"Checks if mock mode is currently enabled.","params":[],"returns":[{"desc":"Whether mock mode is enabled","lua_type":"boolean"}],"function_type":"static","source":{"line":601,"path":"src/init.luau"}},{"name":"clearMockData","desc":"Clears all mock data. Use between tests.","params":[],"returns":[],"function_type":"static","source":{"line":610,"path":"src/init.luau"}},{"name":"transaction","desc":"Executes an atomic transaction between two stores.\\n\\nEither both stores are updated, or neither is (rollback on failure).\\n\\n\\n```lua\\nlocal success, result = Coppermind.transaction(\\n\\tPlayerSchema,\\n\\tsellerKey,\\n\\tbuyerKey,\\n\\tfunction(sellerData, buyerData)\\n\\t\\tif buyerData.coins < 100 then\\n\\t\\t\\treturn false, \\"Not enough coins\\"\\n\\t\\tend\\n\\t\\t\\n\\t\\tsellerData.coins += 100\\n\\t\\tbuyerData.coins -= 100\\n\\t\\treturn true\\n\\tend\\n)\\n```","params":[{"name":"schema","desc":"The schema (both stores must use the same schema)","lua_type":"Schema<T>"},{"name":"keyA","desc":"First store key","lua_type":"string"},{"name":"keyB","desc":"Second store key","lua_type":"string"},{"name":"callback","desc":"Transaction function","lua_type":"(dataA: T, dataB: T) -> (boolean?, string?)"}],"returns":[{"desc":"Whether the transaction succeeded","lua_type":"boolean"},{"desc":"Transaction ID on success, or error message on failure","lua_type":"string?"}],"function_type":"static","source":{"line":685,"path":"src/init.luau"}},{"name":"getPendingTransactionCount","desc":"Gets the number of pending transactions for a store.","params":[{"name":"schema","desc":"The schema","lua_type":"Schema<T>"},{"name":"key","desc":"The store key","lua_type":"string"}],"returns":[{"desc":"Number of pending transactions","lua_type":"number"}],"function_type":"static","source":{"line":786,"path":"src/init.luau"}}],"properties":[{"name":"onLoaded","desc":"Fires when any store finishes loading.","lua_type":"Signal<Store>","source":{"line":801,"path":"src/init.luau"}},{"name":"onSaved","desc":"Fires when any store is saved.","lua_type":"Signal<Store>","source":{"line":808,"path":"src/init.luau"}},{"name":"onError","desc":"Fires when any store encounters an error.","lua_type":"Signal<Store, string>","source":{"line":815,"path":"src/init.luau"}},{"name":"onUnloaded","desc":"Fires when any store is unloaded.","lua_type":"Signal<Store>","source":{"line":822,"path":"src/init.luau"}}],"types":[{"name":"MigrationFn","desc":"A function that transforms data from one version to the next.","lua_type":"(data: {[string]: any}) -> ()","source":{"line":47,"path":"src/init.luau"}},{"name":"Schema","desc":"","fields":[{"name":"name","lua_type":"string","desc":"Unique identifier for the schema (used as DataStore name)"},{"name":"dataTemplate","lua_type":"T","desc":"Default values for new data entries"},{"name":"migrations","lua_type":"{MigrationFn}","desc":"Array of migration functions for schema evolution"}],"source":{"line":56,"path":"src/init.luau"}},{"name":"StoreConfig","desc":"","fields":[{"name":"sessionLocked","lua_type":"boolean?","desc":"Whether to lock this data to the current server session"},{"name":"autoSave","lua_type":"number?","desc":"Auto-save interval in seconds (nil to disable)"}],"source":{"line":68,"path":"src/init.luau"}},{"name":"StoreState","desc":"The current state of a store.\\n- `LOADING`: Data is being loaded from DataStore\\n- `READY`: Data is loaded and available\\n- `SAVING`: Data is being saved to DataStore\\n- `UNLOADING`: Store is being saved and released\\n- `UNLOADED`: Store has been released\\n- `ERROR`: An error occurred during load/save\\n- `SESSION_LOCKED`: Another server has locked this data","lua_type":"\\"LOADING\\" | \\"READY\\" | \\"SAVING\\" | \\"UNLOADING\\" | \\"UNLOADED\\" | \\"ERROR\\" | \\"SESSION_LOCKED\\"","source":{"line":86,"path":"src/init.luau"}},{"name":"Store","desc":"","fields":[{"name":"key","lua_type":"string","desc":"The unique key for this store"},{"name":"data","lua_type":"T?","desc":"The current data (nil while loading)"},{"name":"state","lua_type":"StoreState","desc":"Current state of the store"},{"name":"sessionId","lua_type":"string?","desc":"Session lock ID (if session locked)"},{"name":"version","lua_type":"number","desc":"Data version (for migrations)"},{"name":"lastSaved","lua_type":"number?","desc":"Timestamp of last successful save"},{"name":"onReady","lua_type":"Signal","desc":"Fires when store is ready"},{"name":"onSaved","lua_type":"Signal","desc":"Fires after each successful save"},{"name":"onError","lua_type":"Signal","desc":"Fires on any error"},{"name":"onTransaction","lua_type":"Signal","desc":"Fires when a transaction completes"}],"source":{"line":102,"path":"src/init.luau"}}],"name":"Coppermind","desc":"A robust, feature-rich data persistence library for Roblox.\\n\\n## Features\\n- \ud83d\udcbe Schema-based data management with templates\\n- \ud83d\udd12 Session locking to prevent data corruption\\n- \u23f1\ufe0f Configurable auto-save intervals\\n- \ud83d\udd04 Data migrations for schema evolution\\n- \ud83d\udcb1 Atomic transactions between stores\\n- \ud83e\uddea Mock mode for testing\\n- \ud83d\udce1 Event-driven architecture\\n- \ud83e\uddca Immutable data with deep freeze\\n\\n```lua\\nlocal Coppermind = require(path.to.Coppermind)\\n\\nlocal PlayerSchema = Coppermind.registerSchema({\\n\\tname = \\"PlayerData\\",\\n\\tdataTemplate = {\\n\\t\\tcoins = 0,\\n\\t\\tgems = 0,\\n\\t},\\n\\tmigrations = {},\\n})\\n\\nlocal store = Coppermind.loadStore(PlayerSchema, tostring(player.UserId), {\\n\\tsessionLocked = true,\\n\\tautoSave = 60,\\n})\\n```","source":{"line":34,"path":"src/init.luau"}}')}}]);